// backend/src/billing/invoice-glyphs.ts
//
// Exact glyph outlines for the letters used in the reference invoice's
// "Invoice" title and "RAREPRINT.IN" company name, extracted directly
// from Sale_1263_23-06-2026.pdf's own embedded Type3 font (pikepdf
// content-stream extraction, 2026-08-29) rather than approximated with
// our SegoeUI-Bold.ttf. Matching position+width alone (see invoice-pdf.ts's
// per-character hscale fix) still left a ~1px anti-aliasing fringe under
// pixel-diff comparison, because our font's actual glyph outlines aren't
// byte-identical to the reference's — this file replaces the outlines
// themselves for these two specific fixed strings, eliminating that
// residual entirely.
//
// Coordinates are in em-fraction units (raw Type3 glyph-space units /
// 2048, with the font's FontMatrix y-flip already applied), y-up, origin
// at the glyph's baseline/left-side-bearing-0 point — i.e. multiply by
// (fontSize * scale) to get real point offsets from a char's baseline
// origin. 'm'=moveto, 'l'=lineto, 'c'=cubic bezier (x1,y1,x2,y2,x3,y3),
// 'h'=closepath. Multiple sub-paths per glyph are normal (outer contour +
// inner counter, e.g. the hole in 'o'/'e'/'A') and must all be filled
// together with the nonzero winding rule for the counters to render as
// holes rather than solid blobs.
export type GlyphSeg = ['m', number, number] | ['l', number, number] | ['c', number, number, number, number, number, number] | ['h'];
export type GlyphPath = GlyphSeg[][];

